public enum GroupIntent: Equatable, Hashable {

    case publish(GroupPublicationIntent
    )
    case create(title: String, profile: GroupProfile
    )
    case invite(group: GroupId, recipient: GroupIdentityHash
    )
    case respond(invitation: InvitationId, accept: Bool
    )
    case cancelInvitation(invitation: InvitationId
    )
    case dismissInvitation(invitation: InvitationId
    )
    case removeMember(group: GroupId, member: GroupEndpoint
    )
    case leave(group: GroupId
    )
    case close(group: GroupId
    )
    case deleteLocal(group: GroupId
    )





}

