extension GroupIntent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeGroupIntent: FfiConverterRustBuffer {
    typealias SwiftType = GroupIntent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> GroupIntent {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        case 1: return .publish(try FfiConverterTypeGroupPublicationIntent.read(from: &buf)
        )

        case 2: return .create(title: try FfiConverterString.read(from: &buf), profile: try FfiConverterTypeGroupProfile.read(from: &buf)
        )

        case 3: return .invite(group: try FfiConverterTypeGroupId.read(from: &buf), recipient: try FfiConverterTypeGroupIdentityHash.read(from: &buf)
        )

        case 4: return .respond(invitation: try FfiConverterTypeInvitationId.read(from: &buf), accept: try FfiConverterBool.read(from: &buf)
        )

        case 5: return .cancelInvitation(invitation: try FfiConverterTypeInvitationId.read(from: &buf)
        )

        case 6: return .dismissInvitation(invitation: try FfiConverterTypeInvitationId.read(from: &buf)
        )

        case 7: return .removeMember(group: try FfiConverterTypeGroupId.read(from: &buf), member: try FfiConverterTypeGroupEndpoint.read(from: &buf)
        )

        case 8: return .leave(group: try FfiConverterTypeGroupId.read(from: &buf)
        )

        case 9: return .close(group: try FfiConverterTypeGroupId.read(from: &buf)
        )

        case 10: return .deleteLocal(group: try FfiConverterTypeGroupId.read(from: &buf)
        )

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: GroupIntent, into buf: inout [UInt8]) {
        switch value {


        case let .publish(v1):
            writeInt(&buf, Int32(1))
            FfiConverterTypeGroupPublicationIntent.write(v1, into: &buf)


        case let .create(title,profile):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(title, into: &buf)
            FfiConverterTypeGroupProfile.write(profile, into: &buf)


        case let .invite(group,recipient):
            writeInt(&buf, Int32(3))
            FfiConverterTypeGroupId.write(group, into: &buf)
            FfiConverterTypeGroupIdentityHash.write(recipient, into: &buf)


        case let .respond(invitation,accept):
            writeInt(&buf, Int32(4))
            FfiConverterTypeInvitationId.write(invitation, into: &buf)
            FfiConverterBool.write(accept, into: &buf)


        case let .cancelInvitation(invitation):
            writeInt(&buf, Int32(5))
            FfiConverterTypeInvitationId.write(invitation, into: &buf)


        case let .dismissInvitation(invitation):
            writeInt(&buf, Int32(6))
            FfiConverterTypeInvitationId.write(invitation, into: &buf)


        case let .removeMember(group,member):
            writeInt(&buf, Int32(7))
            FfiConverterTypeGroupId.write(group, into: &buf)
            FfiConverterTypeGroupEndpoint.write(member, into: &buf)


        case let .leave(group):
            writeInt(&buf, Int32(8))
            FfiConverterTypeGroupId.write(group, into: &buf)


        case let .close(group):
            writeInt(&buf, Int32(9))
            FfiConverterTypeGroupId.write(group, into: &buf)


