        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_prns_groups_checksum_method_client_conversation() != 55203) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_prns_groups_checksum_method_client_conversations() != 42649) {
