    if (uniffi_prns_groups_checksum_method_groupobservation_next() != 1238) {
        return InitializationResult.apiChecksumMismatch
    }

    uniffiEnsurePrnsGroupsCoreInitialized()
    uniffiEnsurePrnsGroupsServiceInitialized()
    uniffiEnsurePrnsGroupsStoreRedbInitialized()
    return InitializationResult.ok
